        heading: '契約とは何か',
        body: `契約とは、法的な拘束力をもつ約束のことである。日常の買い物も立派な契約であり、売買契約という。

■ 契約が成立する瞬間
買い手の「これを買います」という意思表示と、売り手の「売ります」という意思表示が合致した時点で成立する。契約書やレシートは証拠にすぎず、口約束でも契約は成立する。コンビニで商品をレジに出し、店員が「はい」と受け取った時点でもう契約である。

■ 契約から生まれる権利と義務
売買契約が成立すると、
・買い手には代金を支払う義務と、商品を受け取る権利
・売り手には商品を引き渡す義務と、代金を受け取る権利
が同時に生じる。だから「気が変わったからやめる」と一方的には言えない。これを契約の拘束力という。

■ 契約自由の原則
誰と、どんな内容の契約を、結ぶか結ばないか、当事者が自由に決められるという近代私法の原則。ただし公序良俗に反する契約や、法律で禁じられた内容の契約は無効になる。

■ 成年年齢の引き下げ
2022年4月から民法が改正され、成年年齢が20歳から18歳になった。未成年者が親の同意なく結んだ契約は取り消せる（未成年者取消権）が、18歳になるとこの保護がなくなる。一方で飲酒・喫煙・公営競技は20歳のまま維持されている。

★ ポイント：高校生のうちに「契約は簡単に成立し、簡単には取り消せない」ことを理解しているかどうかが、消費者トラブルを避ける分かれ目になる。`,
