        body: `クーリング・オフとは、契約後の一定期間内であれば、消費者が理由を示さずに一方的に契約を解除できる制度である。主に特定商取引法が定めている。

■ 8日間の取引
・訪問販売（自宅や職場に来て契約させるもの、キャッチセールス・アポイントメントセールスを含む）
・電話勧誘販売
・特定継続的役務提供（エステティック、語学教室、学習塾、家庭教師、パソコン教室、結婚相手紹介サービスなど）
・訪問購入（業者が家に来て貴金属などを買い取るもの）

■ 20日間の取引
・連鎖販売取引（マルチ商法）
・業務提供誘引販売取引（内職商法・モニター商法）
勧誘の構造が複雑で、被害に気づくまでに時間がかかるため、期間が長く設定されている。

■ 期間の数え方
法定の契約書面（申込書面）を受け取った日を1日目として数える。書面が渡されていなかったり、記載事項に不備があったりした場合は、期間はいつまでも進まない。

■ 対象外になる場合
・通信販売（ネット通販・カタログ通販）…自分で考えて申しこむため不意打ちにあたらない。返品の可否は事業者が示す「返品特約」による。表示がなければ商品到着後8日以内に返品できる。
・自分から店に出向いた店舗販売
・3000円未満の現金取引、化粧品や健康食品など使ってしまった消耗品
・自動車の販売など、政令で除かれているもの

■ 効果と手続き
解除すると契約は最初からなかったことになる。支払ったお金は全額返金され、違約金や損害賠償を請求されない。商品の返送料は事業者が負担する。通知は書面または電子メール等で行い、期間内に発信すれば足りる（到着が期間後でもよい）。証拠を残すため、はがきは特定記録郵便などで送り、コピーを保存する。

⚠ 注意：「クーリング・オフは何でも8日間」と丸暗記するとマルチ商法の20日間を落とす。また「ネット通販もクーリング・オフできる」は典型的な誤り。`,
