        wrongAnswer: 'メーカーの製造工程に過失（手落ち）があったことを証明しなければならない',
        trapExplanation: '民法の不法行為責任の原則（過失責任）をそのまま当てはめてしまう。PL法が作られた理由そのものを押さえていないと、この誤りに陥る。',
