        heading: '消費者行政のしくみと消費者主権',
        body: `法律があっても、被害にあった人が相談できる場所がなければ意味がない。日本には次のしくみがある。

■ 消費者庁（2009年設置）
食品表示は農林水産省、製品事故は経済産業省、悪質商法は警察と、消費者に関わる仕事が各省庁に分かれていたため、被害情報が集まらず対応が遅れた。中国産冷凍ギョーザ事件などをきっかけに、消費者行政の司令塔として内閣府の外局に設置された。消費者庁を監視する第三者機関として消費者委員会も置かれている。

■ 国民生活センターと消費生活センター
国民生活センターは国の機関で、全国の相談情報を集約・分析し、商品テストや注意喚起を行う。消費生活センターは都道府県・市町村が設置する身近な相談窓口で、専門の相談員が助言やあっせん（事業者との交渉の仲立ち）を行う。全国どこからでも「188（いやや）」に電話すれば最寄りの窓口につながる。

■ 情報の非対称性と表示
売り手は商品の中身をよく知っているが、買い手はほとんど知らない。この状態を情報の非対称性という。これをうめるために、食品表示法にもとづく原材料・原産地・アレルギー表示、JISマーク・JASマーク・PSCマークなどの規格表示、景品表示法による不当表示・過大な景品の規制が定められている。

■ 消費者主権
何をどれだけ生産するかは、最終的には消費者が何を買うかによって決まる、という考え方を消費者主権という。裏を返せば、消費者が価格の安さだけで選べば、環境を汚す生産や劣悪な労働条件が温存されてしまう。
・グリーンコンシューマー…環境に配慮した商品を選ぶ消費者
・フェアトレード…発展途上国の生産者に正当な対価を支払う貿易
・エシカル消費（倫理的消費）…人・社会・環境に配慮した消費行動
これらは「選ぶ権利」を積極的に使う実践である。

⚠ 注意：国民生活センターは国の機関、消費生活センターは地方公共団体の機関。名前が似ているので設置主体を取りちがえないこと。`,
