        body: `買う場所の変化は、便利さと同時にいくつもの課題を生んだ。

■ 中心市街地の空洞化
モータリゼーション（自動車の普及）が進み、広い駐車場をもつ郊外型の大型店が有利になった。2000年に大規模小売店舗法が廃止され、大規模小売店舗立地法にかわると、出店規制は「周辺環境への配慮」中心になり、郊外の大型店がさらに増えた。その結果、駅前の商店街は客を失い、閉店した店が並ぶシャッター通りが各地に生まれた。

■ 買い物弱者（買い物難民）
身近な商店が閉店し、自動車を運転できない高齢者などが食料品の購入に困る問題。全国で数百万人規模といわれる。対策として、移動販売車の巡回、宅配サービス、コミュニティバスの運行、集落の共同店舗づくりなどが行われている。

■ 物流の負担
ネット通販の拡大で宅配便の取扱個数が大きく増え、再配達がドライバーの負担を重くしている。宅配ボックスや置き配、コンビニ・駅での受け取りといった工夫が広がった。トラック運転手の時間外労働の上限規制により輸送力の不足が心配される問題は、物流の2024年問題と呼ばれた。

■ 食品ロスと流通
賞味期限の手前で店頭から下げる商慣行などにより、まだ食べられる食品が大量に廃棄されてきた。食品ロス削減推進法（2019年）を受け、期限が近い商品を値引きして売り切るしくみや、フードバンクへの寄付が広がっている。

⚠ 注意：「大規模小売店舗法（大店法）」と「大規模小売店舗立地法（大店立地法）」は別の法律。前者は中小小売店を保護するため出店を規制していたもので、1998年に廃止（2000年施行終了）。後者は騒音や交通渋滞など周辺環境への影響を審査するもので、目的が異なる。`,
