        heading: '独占・寡占と管理価格',
        body: `市場に多数の売り手がいて自由に競争していれば、価格は需要と供給によって決まる。しかし売り手が少なくなると、この前提がくずれる。

■ 独占と寡占
・独占…ある商品の市場を一つの企業が支配している状態。
・寡占…少数の企業が市場の大部分を占めている状態。
現実には完全な独占はまれで、ビール・自動車・携帯電話・板ガラス・鉄鋼など、多くの分野が寡占になっている。生産に巨額の設備投資が必要な産業ほど、新規参入が難しく寡占になりやすい。

■ 管理価格とプライスリーダー
寡占市場では、業界で有力な企業（プライスリーダー＝価格先導者）が価格を決め、他の企業がそれに追随する形で価格が定まる。このように、需要と供給ではなく企業の判断で決められる価格を管理価格という。

■ 価格の下方硬直性
管理価格は、生産費が下がっても引き下げられにくい。値下げをすれば相手も値下げして共倒れになると分かっているため、企業どうしが暗黙のうちに値下げを避けるからである。これを価格の下方硬直性という。消費者にとっては、本来もっと安く買えるはずのものを高く買わされていることになる。

■ 非価格競争
価格で競わないかわりに、デザイン・品質・広告・アフターサービス・おまけといった面で競争が行われる。これを非価格競争という。派手な広告合戦は寡占市場の特徴である。ただし広告費は最終的に価格に上乗せされる。

★ ポイント：「寡占 → 管理価格 → 下方硬直性 → 非価格競争」という流れを一本の線でつないで覚えると、記述問題に対応できる。`,
