        heading: '独占禁止法と公正取引委員会',
        body: `競争が失われると消費者が不利益をこうむるため、法律で競争を守るしくみが必要になる。

■ 競争を妨げる三つの形態
・カルテル（企業連合）…同じ業種の企業が、価格や生産量、販売地域について協定を結ぶ。各企業は独立したまま。価格協定・生産調整など。
・トラスト（企業合同）…同じ業種の複数企業が合併して一つの大企業になる。
・コンツェルン（企業連携）…持株会社などを通じて、異なる業種の企業を資本で支配し、系列化する。戦前の財閥が典型。

■ 独占禁止法
正式名称は「私的独占の禁止及び公正取引の確保に関する法律」。1947年、戦後の経済民主化（財閥解体・農地改革・労働改革のうちの一つ）の一環として制定された。私的独占、不当な取引制限（カルテル）、不公正な取引方法（不当廉売・優越的地位の濫用など）を禁止している。

■ 公正取引委員会
独占禁止法を運用する機関で、内閣府の外局に置かれる。委員長と委員は職権を独立して行使し、内閣から指揮監督を受けない（独立行政委員会）。違反が疑われる企業に立入検査を行い、排除措置命令や課徴金納付命令を出す。カルテルを自主的に申告した企業の課徴金を減免する課徴金減免制度（リーニエンシー）によって、内部からの摘発が進むようになった。

■ 規制緩和との関係
かつて電気・ガス・通信・航空・鉄道などは、法律で参入が制限された規制産業だった。1980年代以降、競争を通じて価格を下げサービスを向上させるため、規制緩和が進められ、電力・ガスの小売り自由化や通信事業への新規参入が実現した。一方、規制緩和が安全性の低下や過度な価格競争を招くという指摘もある。

⚠ 注意：カルテル・トラスト・コンツェルンの区別は頻出。「協定を結ぶだけ＝カルテル」「合併して一つになる＝トラスト」「資本で支配する＝コンツェルン」と、結合の強さの順で覚えるとよい。`,
