        body: `個々の商品の価格ではなく、多くの商品の価格を平均してとらえたものを物価という。代表的な指標は次の二つである。
・消費者物価指数（CPI）…家計が購入する商品・サービスの価格を総合したもの。総務省が作成。
・企業物価指数…企業間で取引される商品の価格。日本銀行が作成。

■ インフレーション
物価が継続的に上昇する現象。同じ1000円札で買えるものが減るので、お金の値打ち（貨幣価値）は下がる。
　物価が2倍になる ＝ 貨幣価値は半分になる
という関係を必ずセットで理解する。

■ デフレーション
物価が継続的に下落する現象。同じ1000円で買えるものが増えるので、貨幣価値は上がる。

■ インフレの原因による分類
・ディマンド・プル・インフレ…好景気で需要が供給を上回り、物価が引き上げられる。
・コスト・プッシュ・インフレ…原油や原材料の価格上昇、賃金上昇などで生産費が上がり、価格に転嫁される。1973年の石油危機（オイルショック）で日本が経験した狂乱物価はこの型である。
・景気が悪いのに物価が上がる状態をスタグフレーションという（stagnation＋inflation）。不況と物価高が同時に起こるため、対策が難しい。

例）年収400万円の人の給料が変わらないまま物価が10％上がった場合、実際に買えるものの量は約9％減る。名目上の収入（名目賃金）が同じでも、物価を考慮した実質賃金は下がっている。

★ ポイント：「名目」と「実質」の区別は入試の頻出テーマ。名目＝そのままの金額、実質＝物価の変動を取り除いた値。`,
