        body: `企業が財やサービスを生み出す活動を生産という。生産には次の三つが必要で、これを生産の三要素という。

■ 土地（自然）
工場や店舗を建てる土地、原材料となる鉱物・水・森林など、自然から得られるもの。

■ 資本
機械・工場・道具・原材料など、生産のために使われるもの。これらを買うための資金も資本と呼ばれる。生産設備を購入することを設備投資という。

■ 労働力
働く人の能力。企業は賃金を支払って労働力を得る。

■ 資本主義経済の特徴
①生産手段（工場・機械・土地）を個人や企業が私有する（私有財産制）。
②利潤を目的として、何をどれだけ作るかを自由に決められる（自由競争）。
③労働力が商品として売買される。
利潤とは、売り上げから生産にかかった費用（原材料費・人件費・設備の減価償却など）を差し引いた残りである。企業は利潤の一部を株主に配当として分け、一部を内部留保として蓄え、一部を新たな設備投資に回す。利潤を設備投資に回して生産規模を大きくしていくことを拡大再生産という。

■ 技術革新（イノベーション）
新しい製品・生産方法・市場を生み出すことをイノベーションという。シュンペーターは、これが資本主義経済を発展させる原動力だと説いた。近年ではAI・ロボット・再生可能エネルギー・バイオテクノロジーなどの分野で競争が激しい。

★ ポイント：「利潤＝売り上げ－費用」。売り上げそのものを利潤と混同しないこと。`,
