        body: `企業は、誰が出資し何を目的とするかによって大きく二つに分かれる。

■ 私企業（民間企業）
利潤を得ることを目的として、個人や民間の団体が経営する企業。
・個人企業…個人商店、農家など。設立は簡単だが、事業の借金に個人の財産すべてで責任を負う（無限責任）。
・法人企業…法律上の人格をもつ企業。株式会社、合同会社、合名会社、合資会社の四つが会社法で定められている。現在、新たに設立できる会社はこの四種類で、有限会社は2006年施行の会社法により新設できなくなった（既存のものは特例有限会社として存続）。
・組合企業…農業協同組合（JA）、漁業協同組合、生活協同組合（生協）など。組合員の相互扶助を目的とする。

■ 公企業
国や地方公共団体が資金を出して経営し、利潤より公共の利益を目的とする企業。
・地方公営企業…水道、市営バス・地下鉄、公立病院、下水道など。
・独立行政法人・特殊法人…造幣局、国立印刷局、日本年金機構など。

■ 民営化の流れ
かつては国が直接経営する公社・公団が多かったが、効率化と財政負担の軽減を目的に民営化が進んだ。
・1985年…日本電信電話公社 → NTT、日本専売公社 → JT
・1987年…日本国有鉄道（国鉄）→ JR各社
・2005年…道路関係四公団 → 高速道路会社
・2007年…日本郵政公社 → 日本郵政グループ
民営化により競争が生まれ料金やサービスが改善した面がある一方、採算のとれない地方路線の廃止など、公共性が損なわれる懸念も指摘される。

⚠ 注意：公企業は「利潤を目的としない」だけで、料金をとらないわけではない。水道もバスも料金を徴収して費用をまかなっている。`,
