        body: `株式会社は、出資する人と経営する人が分かれた組織である。

■ 株主総会
株式会社の最高議決機関で、少なくとも年に一度開かれる。
・取締役や監査役の選任・解任
・決算（貸借対照表・損益計算書）の承認
・配当額の決定
・定款の変更、合併、解散など重要事項の決定
を行う。議決権は持ち株数に応じるため、株式の過半数を持つ株主は事実上、会社の意思決定を左右できる。

■ 取締役会
株主総会で選ばれた取締役が構成し、会社の業務執行を決定する。代表取締役（社長など）が日常の経営を行う。監査役は取締役の職務を監査する。

■ 所有と経営の分離
株式が多くの人に分散すると、株主一人ひとりは経営に関わらず、専門的な知識をもつ経営者が実際の経営を担うようになる。これを所有（資本）と経営の分離という。株主は「会社の持ち主」でありながら、日々の経営には直接タッチしない。

■ コーポレート・ガバナンス
経営者が株主や社会の利益に反する行動をとらないよう監視するしくみを企業統治（コーポレート・ガバナンス）という。社外取締役の導入、監査法人による会計監査、情報公開（ディスクロージャー）などがその手段である。不正会計や不祥事が相次いだことで、その重要性が高まっている。

■ 資金調達の二つの方法
・自己資本…株式の発行、内部留保。返済の必要がない。
・他人資本…銀行からの借り入れ、社債の発行。返済の義務と利子の負担がある。
株式で集めた資金は返さなくてよいかわりに、配当と経営への発言力を株主に渡すことになる。

⚠ 注意：株主総会は「最高議決機関」、取締役会は「業務執行を決定する機関」。株主総会を「経営を行う機関」と書くと誤りになる。`,
