        heading: 'バブル経済とその教訓',
        body: `株価や地価が、企業の実力や土地の利用価値からかけ離れて上昇することがある。この状態をバブル（泡）という。

■ バブル経済の発生
1985年のプラザ合意によって急激な円高が進み、輸出産業が打撃を受けた（円高不況）。政府と日本銀行は景気を支えるため金利を大幅に引き下げた。だぶついた資金は設備投資だけでなく株式や土地の購入に向かい、「地価は絶対に下がらない」という土地神話も手伝って、1980年代後半に株価と地価が異常に高騰した。日経平均株価は1989年末に史上最高値をつけた。

■ 崩壊とその後
過熱を抑えるため日本銀行が金融引き締めに転じ、政府が土地取引を規制すると、1991年ごろから株価と地価が急落した。
・企業…資産価値が下がり、借金だけが残る。設備投資を控え、リストラを行う。
・銀行…回収できない不良債権を大量にかかえ、貸し出しに慎重になる（貸し渋り）。1990年代後半には大手金融機関の破綻も起きた。
・家計…雇用不安と所得の伸び悩みで消費が落ちこむ。
この結果、日本経済は長期の停滞に入り、「失われた10年」「失われた30年」と呼ばれた。デフレが続き、企業は内部留保を厚くして投資を抑える傾向が強まった。

■ 教訓
資産価格の上昇が実体経済の成長を大きく上回るとき、その多くは持続しない。投資には元本が保証されない価格変動リスクがあり、預金とは性質が異なる。金融商品の性質を理解して選ぶ力（金融リテラシー）の育成が、2022年度から高校の家庭科などで重視されるようになった。

⚠ 注意：株式は元本保証がない。「必ずもうかる」という勧誘は、消費者契約法の断定的判断の提供にあたり違法である。`,
