        body: `企業は利潤を追求する組織だが、同時に社会の一員でもある。従業員、消費者、取引先、地域住民、株主、行政など多くの関係者（ステークホルダー）に影響を与えるからである。こうした関係者に対して企業が果たすべき責任を、企業の社会的責任（CSR）という。

■ CSRの主な内容
①法令の遵守（コンプライアンス）
　法律を守るのは当然として、社会常識や倫理にも従う。不正会計、燃費や品質検査データの改ざん、産地偽装、談合などは、法令違反であると同時に企業の信用を根本から損なう。
②消費者の安全と製品の品質確保
　欠陥商品の速やかな回収（リコール）、正確な表示。
③環境への配慮
　排出物の管理、省エネルギー、再生可能エネルギーの利用、リサイクルの推進。
④雇用の維持と働きやすい職場づくり
　安易な人員削減を避け、労働災害を防ぎ、多様な人材が働ける環境を整える。
⑤情報公開（ディスクロージャー）
　財務諸表や環境報告書を公開し、株主や社会が判断できるようにする。
⑥地域社会への貢献
　メセナ（音楽・美術など文化活動の支援）、フィランソロピー（寄付やボランティアなどの慈善活動）、災害時の支援。

★ ポイント：CSRは「余裕があればやる慈善活動」ではなく、企業が存続するための条件になっている。不祥事を起こした企業が、売り上げの減少や取引の停止によって経営危機に陥る例は多い。`,
