        body: `労働組合は、労働者が団結して使用者と対等に交渉するための組織である。

■ 組合の形態
・企業別組合…同じ企業の従業員で組織する。日本の労働組合の圧倒的多数がこの形。
・産業別組合…同じ産業で働く人が企業の枠をこえて組織する。欧米で主流。
・職業別組合…同じ職種の人が組織する。
・合同労組（ユニオン）…企業や産業をこえて個人単位で加入できる組合。中小企業の労働者や非正規雇用の労働者が個人で加入する例が増えている。

企業別組合には、会社の事情を踏まえた話し合いがしやすい反面、雇用を守ることが優先されて賃上げの要求が弱まりやすい、非正規労働者が組合に入れないことが多い、という弱点がある。

■ 労働協約
組合と使用者が交渉して結ぶ協定。個々の労働契約より強い効力をもち、労働協約に反する労働契約の部分は無効となる。効力の強さは 法令 ＞ 労働協約 ＞ 就業規則 ＞ 労働契約 の順である。

■ 春闘
毎年2月から3月にかけて、産業ごとに労働組合が足並みをそろえて賃上げ交渉を行う日本独特の慣行。有力企業の回答が相場となり、中小企業や未組織の職場の賃金にも波及する。近年は物価上昇を背景に高い賃上げ率が実現し、政労使の会議で賃上げが議論されるようになった。

■ 組織率の低下
労働組合の推定組織率は、1950年代には5割近くあったが、その後低下を続け、現在は16％台である。低下の理由は、
・産業構造の変化（組合が強かった製造業の比重が下がり、サービス業が拡大）
・パート・アルバイト・派遣など、組合に入りにくい非正規雇用の増加
・中小企業では組合が結成されにくいこと
・個人の意識の変化
などである。ただしパートタイム労働者の組合員数は増加傾向にある。

★ ポイント：「企業別組合が中心」「組織率は約16％台」という二点は、日本の労働組合を答えさせる問題の定番である。`,
