        heading: '不当労働行為と労働争議の解決',
        body: `団結権が保障されていても、使用者が組合をつぶそうとすれば意味がない。そこで労働組合法は次の行為を不当労働行為として禁止している。

■ 不当労働行為の類型
①不利益取扱い…組合員であることや組合活動をしたことを理由に、解雇・降格・減給などの不利益を与える。
②黄犬契約…「組合に入らないこと」を雇用の条件とする。
③団体交渉の拒否…正当な理由なく団体交渉に応じない。
④支配介入…組合の運営に口を出す、組合の運営費を援助する（御用組合づくり）。
これらが行われた場合、労働者や組合は労働委員会に救済を申し立てることができ、労働委員会は原状回復などの救済命令を出す。

■ 争議行為
交渉が行きづまったとき、労働者側は次の手段をとれる。
・ストライキ（同盟罷業）…集団で労務の提供を拒む。
・サボタージュ（怠業）…作業能率を意図的に落とす。
・ピケッティング…職場の入口で就労しないよう呼びかける。
使用者側の対抗手段としてロックアウト（作業所閉鎖）がある。正当な争議行為であれば、労働者は刑事責任も民事上の損害賠償責任も問われない（労働組合法第1条第2項・第8条）。

■ 労働関係調整法による調整
争議が長引けば労使双方にも社会にも損失が大きい。そこで労働委員会が次の三段階で調整する。
①斡旋…斡旋員が双方の言い分を聞いて話し合いを取り持つ。最も緩やかな手段。
②調停…調停委員会が調停案を作成して受諾を勧める。受け入れるかは当事者の自由。
③仲裁…仲裁委員会が裁定を下す。労働協約と同じ効力をもち、当事者を拘束する。
拘束力の強さは 斡旋 ＜ 調停 ＜ 仲裁 の順である。

■ 個別労働紛争
近年は組合を通じた集団的な争議より、解雇・パワーハラスメント・雇い止めなど個人と会社の紛争が増えている。都道府県労働局のあっせん、労働審判制度（裁判所で原則3回以内の期日で解決をはかる）などが利用されている。

⚠ 注意：労働委員会は行政委員会であって裁判所ではない。仲裁裁定は拘束力をもつが、判決とは異なる。`,
