        body: `高度経済成長期に定着した日本の雇用の特徴は、次の三つにまとめられる。

■ 終身雇用
新卒で採用された正社員は、定年まで同じ企業で働き続けることが前提とされた。企業は長期的な視点で社内教育に投資でき、労働者は生活の見通しを立てられた。

■ 年功序列賃金
勤続年数と年齢に応じて賃金が上がるしくみ。若いうちは働きに比べて賃金が低く、中高年になると高くなる。家族を養う費用が増える時期に賃金が高くなる点で、生活を支える機能をもっていた。

■ 企業別労働組合
組合が企業ごとに組織され、労使が協調的に交渉する。

■ 崩れた理由
・バブル崩壊後の長期不況で、企業が人件費の削減を迫られた。
・国際競争が激化し、需要の変動に応じて雇用量を調整する必要が高まった。
・技術革新が速くなり、長期の社内教育より外部からの人材確保が有利な場面が増えた。
・少子高齢化で若年層が減り、年功序列賃金を支える人口構成が崩れた。
その結果、成果主義（能力や実績に応じて賃金を決める）を導入する企業が増え、中途採用や転職も一般的になった。近年は人手不足を背景に、初任給の引き上げや職務給への転換も進んでいる。

★ ポイント：終身雇用・年功序列は法律で定められた制度ではなく、あくまで慣行である。だから経済状況の変化とともに変わりうる。`,
