        heading: '二本の曲線の向きを間違えない',
        body: `需要と供給のグラフは、公民の経済分野で最も出題される図である。まず軸と向きを確実にする。

■ 軸の取り方
　縦軸（y軸）＝価格　　横軸（x軸）＝数量
これが約束である。数学のグラフとは逆に感じるかもしれないが、経済学の慣習としてこの形が使われる。

■ 需要曲線は右下がり
需要とは、消費者が「その価格で買いたい」と思う量である。
・価格が高い → 買うのをやめる人が増える → 需要量は少ない（グラフの左上）
・価格が安い → 買う人が増える、一人あたりの購入量も増える → 需要量は多い（グラフの右下）
したがって、左上から右下へ向かう右下がりの線になる。

■ 供給曲線は右上がり
供給とは、生産者が「その価格で売りたい」と思う量である。
・価格が高い → 作れば作るほどもうかる → 増産する、新しい企業も参入する → 供給量は多い（右上）
・価格が安い → 費用に見合わず作らない、撤退する → 供給量は少ない（左下）
したがって、左下から右上へ向かう右上がりの線になる。

■ 覚え方
「買う人（需要）は安いほどうれしいので、右（数量が多い方）へ行くほど価格は下がる」＝右下がり。
「売る人（供給）は高いほどうれしいので、右へ行くほど価格は上がる」＝右上がり。
図を描くときは必ず「需要＝D（demand）」「供給＝S（supply）」の文字を書きこみ、どちらの線かを明示すること。

⚠ 注意：需要曲線と供給曲線を逆に描くと、その後の問題がすべて逆の結論になる。試験では最初に向きを確認する習慣をつける。`,
