        heading: '価格が高すぎるとき・低すぎるとき',
        body: `均衡価格からずれた価格では、必ず「余る」か「足りない」かのどちらかが起こる。

■ 均衡価格より高い場合
価格が高いので、
・消費者は買いひかえる → 需要量は少ない
・生産者は多く作りたい → 供給量は多い
その結果、供給量が需要量を上回る。この状態を超過供給といい、現実には売れ残りとして現れる。売れ残りをかかえた売り手は値下げをするので、価格は下がっていく。値下げが進むと需要量が増え、供給量は減るので、やがて均衡価格に近づく。

■ 均衡価格より低い場合
価格が安いので、
・消費者は多く買いたい → 需要量は多い
・生産者は作っても利益が出ない → 供給量は少ない
その結果、需要量が供給量を上回る。これを超過需要といい、現実には品不足・行列・売り切れとして現れる。買い手は多少高くても手に入れようとし、売り手も値上げできるので、価格は上がっていく。値上げが進むと需要量が減り供給量が増えるので、やがて均衡価格に近づく。

■ グラフでの読み取り方
①問われている価格の高さで、横に水平線を引く。
②その線が需要曲線と交わる点までの横の長さ ＝ その価格での需要量
③その線が供給曲線と交わる点までの横の長さ ＝ その価格での供給量
④二つを比べ、長いほうが多い。差が超過分の大きさである。
均衡点より上に線を引けば供給側が長く（超過供給）、下に引けば需要側が長く（超過需要）なる。

★ ポイント：「上は売れ残り、下は品不足」。均衡点より上か下かだけで判断できるので、迷ったらグラフに水平線を引く。`,
