        body: `価格の自動調節作用は強力だが、いつでもうまく働くわけではない。

■ 供給の調整に時間がかかる場合
農産物は種をまいてから収穫まで時間がかかるため、価格が上がってもすぐには増産できない。逆に、価格が上がったのを見て多くの農家が作付けを増やすと、翌年には供給が過剰になって価格が暴落する。この振動をくり返す現象は、グラフの形からくもの巣理論と呼ばれる。キャベツやレタスの豊作貧乏がその例である。
住宅も、着工から完成まで年単位の時間がかかるため、価格の変動が大きくなりやすい。

■ 需要が価格に反応しにくい場合
米・電気・水道・医薬品のような生活必需品は、値上がりしても買う量をあまり減らせない。この性質を「需要の価格弾力性が小さい」という。逆に、宝飾品や旅行のようなぜいたく品は、値上がりすれば買うのをやめられるので弾力性が大きい。
弾力性が小さい商品は、供給が少し減っただけで価格が大きく跳ね上がる。石油危機のときに石油価格が急騰したのはこのためである。

■ 価格を人為的に固定した場合
政府が価格の上限や下限を定めると、自動調節が働かなくなる。
・上限価格（価格を均衡より低く固定）…慢性的な品不足が生じ、行列・配給・闇取引が発生する。
・下限価格（価格を均衡より高く固定）…慢性的な売れ残りが生じ、過剰在庫を政府が買い上げることになる。かつての食糧管理制度で米の過剰在庫が問題になったのがこの例である。

⚠ 注意：「超過供給だから供給が多すぎる」＝生産者が悪い、という話ではない。超過は「その価格において」生じるものであり、価格が変われば解消する。原因を価格に求める視点をもつこと。`,
