・規制が新規参入を妨げ、競争を弱める
・行政の肥大化により無駄な支出が増える
・利害関係者の圧力で政策がゆがむ
これを政府の失敗という。だからこそ、行政改革や規制緩和、政策評価、情報公開が求められる。

