        heading: '貨幣のはたらき',
        body: `貨幣がなかった時代、人々は物と物を直接交換していた（物々交換）。しかしこの方法には大きな不便がある。自分がほしい物をもっていて、しかも自分の持ち物をほしがっている相手を見つけなければならない（欲望の二重の一致）。魚は日もちしないので価値を蓄えることもできない。

■ 貨幣の三つのはたらき
①交換（支払い）の手段
　貨幣を仲立ちにすれば、相手が何をほしがっているかに関係なく取引できる。
②価値の尺度
　あらゆる物の価値を「円」という共通の単位で表せる。りんご1個150円、映画1本2000円というように比較できる。
③価値の保存（貯蔵）の手段
　腐らないので、価値を将来へ持ちこせる。今日の収入を来年の支出に回せる。

■ 通貨の種類
・現金通貨…日本銀行券（紙幣）と硬貨。日本銀行券は日本銀行が発行し、硬貨は政府（造幣局が製造）が発行する。発行元が異なる点は頻出。
・預金通貨…銀行の普通預金・当座預金。小切手や振込によって支払いに使えるので通貨として扱う。金額でみると、現金通貨より預金通貨のほうがはるかに大きい。
・電子マネー・キャッシュレス決済…現金通貨や預金通貨を電子的に動かすしくみ。それ自体が新しい通貨というより、決済の手段である。

■ 管理通貨制度
かつては金と交換できることを保証した兌換紙幣が使われていた（金本位制）。現在は、金との交換が保証されない不換紙幣を、中央銀行が経済の状況に応じて量を管理して発行している。これを管理通貨制度という。紙幣そのものに価値があるのではなく、国家と中央銀行への信用によって通用している。

★ ポイント：「日本銀行券＝日本銀行が発行」「硬貨＝政府が発行」。この使い分けは選択肢問題で狙われる。`,
