        body: `銀行は金融機関の中心にある存在で、次の三つの業務を行う。

■ ①預金業務
家計や企業から資金を預かる。普通預金、定期預金、当座預金などの種類がある。預金者には利子（預金金利）が支払われる。

■ ②貸出業務
集めた資金を、資金を必要とする企業や家計に貸し出す。借り手は元金に加えて利子（貸出金利）を支払う。銀行は返済能力を審査し、担保を求めることもある。

■ ③為替業務
現金を実際に運ばずに、口座間の記録の書きかえによって支払いを済ませる。振込、口座振替、送金、外国への送金（外国為替）など。公共料金の自動引き落としもこの業務である。

■ 利ざや
　貸出金利 － 預金金利 ＝ 利ざや
これが銀行の基本的な収入源である。たとえば預金金利が年0.1％、貸出金利が年2％であれば、その差の1.9％分が銀行の収入になる。ただし借り手が返済できなければ損失（不良債権）となるため、審査が重要になる。

■ 信用創造のしくみ
銀行は、預かった預金のすべてを手もとに置いておく必要はない。預金者全員が同時に引き出すことはないからである。預金の一部を支払い準備として残し、残りを貸し出す。
例）準備率10％の場合
・A銀行が100万円の預金を受け入れる → 10万円を残し90万円を貸し出す
・貸し出された90万円がB銀行に預金される → 9万円を残し81万円を貸し出す
・さらに81万円がC銀行に預金される → …
このくり返しにより、最初の100万円の預金から、理論上は最大で1000万円（100万円÷0.1）の預金通貨が生み出される。新たに創造された額は1000万円－100万円＝900万円である。これを信用創造という。

★ ポイント：信用創造の計算では「最初の預金÷準備率＝生み出される預金総額」。信用創造額（新たに創られた額）を問われたら、そこから最初の預金を引く。`,
