        heading: '累進課税のしくみ',
        body: `所得が高い人ほど高い税率で課税する方式を累進課税という。日本では所得税、相続税、贈与税に採用されている。

■ 所得税の税率（課税所得金額に対して）
　195万円以下…………………………… 5％
　195万円超 330万円以下…………… 10％
　330万円超 695万円以下…………… 20％
　695万円超 900万円以下…………… 23％
　900万円超 1800万円以下………… 33％
　1800万円超 4000万円以下……… 40％
　4000万円超……………………………… 45％
の7段階である。これに復興特別所得税と、住民税（一律10％）が加わる。

■ 超過累進税率という考え方
ここが最重要である。課税所得が400万円の人の税額は「400万円×20％」ではない。所得を区分ごとに切り分け、それぞれの区分に対応する税率をかけて合計する。
　195万円までの部分…195万円×5％＝9万7500円
　195万円超330万円までの部分…135万円×10％＝13万5000円
　330万円超400万円までの部分…70万円×20％＝14万円
　合計 37万2500円
このように、区分を超えた部分にだけ高い税率がかかる。全体に一律で高い税率がかかるのではない。

■ なぜこの方式か
もし「330万円を1円でも超えたら全額に20％」という仕組みなら、所得がわずかに増えただけで手取りが逆に減ってしまい、働く意欲をそぐ。超過累進税率であれば、所得が増えれば必ず手取りも増える。

★ ポイント：「所得が増えて税率区分が上がると、かえって手取りが減る」というのは誤解である。増えた部分にだけ高い税率がかかるので、手取りが逆転することはない。`,
