        body: `消費税は、商品やサービスの消費に対して広く課される間接税である。

■ 導入と引き上げの経過
・1989年…税率3％で導入（竹下内閣）。
・1997年…5％へ引き上げ（橋本内閣）。
・2014年…8％へ引き上げ。
・2019年…10％へ引き上げ。同時に軽減税率制度を導入。
引き上げのたびに大きな政治的争点となり、内閣の支持率や選挙結果を左右してきた。

■ 軽減税率
2019年から、次のものは税率8％に据え置かれている。
・飲食料品（酒類と外食を除く）
・週2回以上発行される新聞の定期購読
持ち帰りは8％、店内での飲食は10％というように、同じ商品でも扱いが変わる場面があり、事業者の事務負担が増えるという指摘もある。

■ なぜ消費税なのか
①税収が安定する…景気に左右されにくい。所得税や法人税は不況時に大きく落ちこむ。
②世代間の公平…所得税と社会保険料は働く世代に集中するが、消費税は消費するすべての世代が負担する。高齢化が進み、支えられる側が増えるなかで、負担を広く分かち合う必要がある。
③国際的な水準…ヨーロッパ諸国の付加価値税は20％前後で、日本の10％は高くない。

■ 使い道
2012年の社会保障と税の一体改革により、消費税の税収は年金・医療・介護・少子化対策という社会保障四経費にあてることが法律で定められた。増収分は社会保障の充実と安定化に使うという整理である。

★ ポイント：導入年（1989年）と各引き上げの年（1997・2014・2019年）、および軽減税率の対象は、そのまま出題される。`,
