        heading: '逆進性という問題',
        body: `消費税の最大の問題は逆進性である。

■ 逆進性とは
所得の低い人ほど、所得に対する税負担の割合が重くなる性質をいう。
例）年収200万円の人と年収1000万円の人を比べる。
　年収200万円の人…生活のために年180万円を消費 → 消費税（10％）は18万円 → 所得に対する負担率9％
　年収1000万円の人…年500万円を消費し、残りは貯蓄 → 消費税は50万円 → 所得に対する負担率5％
税率は同じ10％でも、所得に対する負担の割合は低所得者のほうが重くなる。所得が低いほど、収入のうち消費に回す割合（消費性向）が高くなるからである。

■ 逆進性への対策
・軽減税率…生活必需品である食料品の税率を低く抑える。ただし高所得者も同じ恩恵を受けるため、格差是正の効果は限定的だという指摘もある。
・給付付き税額控除…所得税から控除し、控除しきれない低所得者には現金を給付する方式。カナダなどが採用。所得の把握が前提となるため、日本ではマイナンバー制度の整備とあわせて議論されている。
・低所得者向けの給付金…臨時的な現金給付。
・社会保障の充実…集めた税を給付として低所得層に手厚く配れば、税と給付を合わせた再分配の効果は改善する。

■ 消費税をめぐる論点
・引き上げは消費を冷やし、景気を悪化させるという批判がある。実際、1997年と2014年の引き上げ後には消費の落ちこみが見られた。
・一方、社会保障費が毎年増加するなかで、国債発行に頼り続ければ将来世代に負担を先送りすることになる。
・インボイス制度（適格請求書等保存方式、2023年開始）により、免税事業者だった小規模事業者の負担が増えたという課題も生じた。

■ 公平をどう考えるか
・垂直的公平を重んじれば、累進的な所得税を強化すべきだという結論になる。
・水平的公平と世代間の公平を重んじれば、消費税に比重を置くべきだという結論になる。
どちらの立場にも根拠があり、正解は一つではない。記述問題では、どちらの立場に立つかを明示し、根拠と対応策をセットで述べることが求められる。

⚠ 注意：逆進性は「低所得者のほうが税額が大きい」という意味ではない。税額そのものは高所得者のほうが大きい。所得に対する「割合」が重くなるという点を正確に書くこと。`,
