        body: `税収などで歳出をまかなえないとき、国は国債を発行して不足分を借り入れる。

■ 国債とは
国が発行する債券で、購入者に対して満期に元本を返し、それまで利子を支払うことを約束する。購入するのは主に金融機関、保険会社、年金基金などで、日本銀行も市場を通じて大量に保有している。日本の国債は大部分が国内で保有されている点が特徴である。

■ 二つの種類
・建設国債（4条国債）…道路、橋、港湾、学校など、社会資本の整備にあてる。財政法第4条のただし書きで認められている。作られた施設は将来の世代も利用するので、将来世代が費用を分担するのは公平だという考え方にもとづく。
・赤字国債（特例国債）…人件費や社会保障費など、その年に消えてしまう経常的な支出をまかなう。財政法は認めていないため、毎年度、特例法を制定して発行している。1975年度に発行が始まり、バブル期の数年を除いてほぼ毎年発行されている。

■ 財政法の原則
財政法第4条は「国の歳出は公債または借入金以外の歳入をもって財源としなければならない」と定めている。安易な借金が戦前の軍事費膨張につながった反省にもとづく規定である。しかし現実には、例外であるはずの国債発行が常態化している。

■ 残高の規模
普通国債の残高は1000兆円を超え、地方の債務を合わせた長期債務残高は1200兆円を上回る。国内総生産（GDP）に対する比率は2倍を超え、主要先進国のなかで最も高い水準にある。

★ ポイント：建設国債は財政法が例外として認めるもの、赤字国債は毎年の特例法によるもの。この違いは頻出である。`,
