        heading: '給付費の規模と財源',
        body: `社会保障給付費は年々増加し、総額は130兆円を超えている。国民所得に対する比率も上昇を続けている。

■ 給付費の内訳
・年金…約4割。最大の項目。
・医療…約3割。
・福祉その他（介護を含む）…約3割弱。
高齢者向けの給付が全体の大部分を占める一方、児童・家族関係の給付は相対的に小さい。「高齢者に手厚く、現役世代・子育て世代に薄い」という指摘があり、こども家庭庁の設置や児童手当の拡充など、子育て支援の強化が進められている。

■ 財源
・保険料…被保険者と事業主が負担する。給付費の約6割。
・公費（税）…国と地方が負担する。約4割。
・その他…資産収入など。
社会保険であっても保険料だけではまかなえず、多額の税が投入されている。基礎年金の給付費の2分の1は国庫が負担している。

■ 高福祉高負担と低福祉低負担
・スウェーデンなど北欧型…給付は手厚いが、税と社会保険料の負担も重い（高福祉高負担）。
・アメリカ型…公的な給付は限定的で、負担も軽い。医療は民間保険が中心（低福祉低負担）。
・日本…両者の中間。国民負担率（税と社会保険料が国民所得に占める割合）は4割台後半である。
どの水準を選ぶかは、社会がどのような価値を重んじるかという選択である。

■ ナショナル・ミニマムとセーフティネット
国が保障すべき最低限度の生活水準をナショナル・ミニマムという。1942年にイギリスで出されたベバリッジ報告は「ゆりかごから墓場まで」という言葉で知られ、戦後の各国の社会保障制度に大きな影響を与えた。社会保障は、誰もが人生のどこかで直面しうるリスク（病気・失業・老い・障害）に社会全体で備える安全網（セーフティネット）である。

⚠ 注意：生活保護（公的扶助）は保険料を払っていなくても受けられる。保険料を前提とする社会保険とは、財源も考え方も異なる。`,
