        heading: '人口構成の変化を読む',
        body: `社会保障の問題は、人口構成の変化から生じている。

■ 高齢化率の段階
65歳以上の人口が総人口に占める割合を高齢化率という。
・7％以上…高齢化社会
・14％以上…高齢社会
・21％以上…超高齢社会
日本は1970年に7％、1994年に14％、2007年に21％を超えた。7％から14％に達するまでの年数（倍加年数）はわずか24年で、フランスの115年、スウェーデンの85年と比べて極端に速い。現在の高齢化率は約29％で、世界で最も高い水準である。

■ 少子化
一人の女性が生涯に産む子どもの数の平均を合計特殊出生率という。人口を維持するには約2.07が必要（人口置換水準）だが、日本は1975年に2.0を下回り、2005年に1.26まで低下、その後わずかに回復したのち再び低下して1.2前後になっている。年間の出生数も減少を続け、80万人を下回った。
少子化の背景には、
・晩婚化・未婚化
・子育てと仕事の両立の困難
・教育費など子育ての経済的負担
・非正規雇用の増加による所得の不安定さ
・住宅事情
などが重なっている。

■ 人口ピラミッドの変化
かつての富士山型（若年層が多い）から、つりがね型を経て、現在はつぼ型（若年層が少なく高齢層が多い）へ変化した。将来推計では、いっそう上が重い形になる。

■ 何が起こるか
・社会保障の担い手の減少と受け手の増加
・労働力不足
・地方の過疎化、集落の維持困難
・空き家の増加
・経済規模の縮小

★ ポイント：「1970年に7％、1994年に14％、2007年に21％」という三つの年と、倍加年数24年という数字は記述でも使える。`,
