        heading: '年金のしくみと種類',
        body: `公的年金は二階建ての構造になっている。

■ 1階：国民年金（基礎年金）
20歳以上60歳未満のすべての国民が加入する。
・第1号被保険者…自営業者、学生、無職の人。保険料を自分で納める。
・第2号被保険者…会社員、公務員。厚生年金の保険料に含まれる形で負担する。
・第3号被保険者…第2号被保険者に扶養されている配偶者。個別の保険料負担はない。
学生には在学中の保険料納付を猶予する学生納付特例制度があり、所得が少ない人には免除制度がある。未納のまま放置すると、老齢年金だけでなく障害年金も受けられなくなるおそれがあるため、手続きを行うことが重要である。

■ 2階：厚生年金
会社員と公務員が加入し、基礎年金に上乗せして支給される。保険料は報酬に比例し、事業主と被保険者が折半する（保険料率18.3％）。かつて公務員は共済年金だったが、2015年に厚生年金へ一元化された。

■ 三種類の給付
・老齢年金…原則65歳から支給。受給開始を遅らせれば（繰り下げ受給）給付額は増え、早めれば（繰り上げ受給）減る。
・障害年金…病気やけがで一定以上の障害が残ったときに支給。年齢に関係なく受け取れる。
・遺族年金…被保険者が亡くなったとき、生計を維持されていた遺族に支給。
若い人にとっても、障害年金と遺族年金の存在は大きな意味をもつ。「年金＝老後のもの」ではない。

■ 私的年金
公的年金に上乗せする制度として、企業年金、iDeCo（個人型確定拠出年金）、国民年金基金などがある。公的年金だけで生活のすべてをまかなうのが難しくなるなか、自助努力による備えも重視されている。

⚠ 注意：日本の公的年金は加入が義務であり、任意ではない。「払いたくないから加入しない」という選択はできず、未納には督促や差し押さえが行われることもある。`,
