        body: `社会保障は制度だけで完結しない。誰もが暮らしやすい社会をつくる発想が必要になる。

■ ノーマライゼーション
障害のある人もない人も、高齢者も若者も、特別に分けられることなく、地域のなかでともに普通に生活できる社会が正常（ノーマル）な社会である、という考え方。1950年代のデンマークで生まれ、世界に広がった。施設に隔離するのではなく、地域で暮らせるように支えるという転換をもたらした。

■ バリアフリー
生活のなかにある障壁（バリア）を取り除くこと。四つの障壁がある。
①物理的な障壁…段差、狭い通路 → スロープ、エレベーター、点字ブロック
②制度的な障壁…資格や入試の制限 → 受験時の配慮、採用の見直し
③文化・情報面の障壁…音声のみの案内、難しい表現 → 手話、字幕、点字、やさしい日本語
④意識上の障壁…偏見や無関心 → 教育、交流
バリアフリー法（高齢者、障害者等の移動等の円滑化の促進に関する法律）により、駅や公共施設のバリアフリー化が進められている。

■ ユニバーサルデザイン
はじめから、年齢・性別・障害の有無・言語にかかわらず、誰もが使いやすいように設計すること。
例）シャンプー容器の側面のギザギザ、多機能トイレ、自動ドア、ピクトグラム（絵文字による案内）、幅の広い改札、レバー式の水道栓、多言語表示
バリアフリーが「あとから障壁を取り除く」のに対し、ユニバーサルデザインは「はじめから障壁を作らない」という違いがある。

■ 障害者の権利と法制度
・障害者基本法…障害者の自立と社会参加の支援を定める。
・障害者差別解消法（2016年施行）…障害を理由とする不当な差別的取扱いを禁止し、合理的配慮の提供を求める。2024年からは民間の事業者にも合理的配慮の提供が義務づけられた。
・障害者雇用促進法…一定規模以上の事業主に法定雇用率以上の障害者雇用を義務づける。
・障害者権利条約…2006年に国連で採択、日本は2014年に批准した。
合理的配慮とは、障害のある人から求めがあったとき、過重な負担にならない範囲で、その人が支障なく参加できるよう調整することをいう（筆談での対応、座席の配慮、時間の延長など）。

■ 社会保障を支えるもの
公的な制度（公助）だけでなく、自分で備えること（自助）、家族や地域で助け合うこと（互助・共助）が組み合わさって暮らしは支えられる。ボランティアやNPOの活動も重要な役割を果たしている。

⚠ 注意：バリアフリーとユニバーサルデザインは、「あとから取り除く」か「はじめから作らない」かで区別する。両者を同じ意味で使うと減点されることがある。`,
